import tarfile
import os

def readArchive(fileName):
    targetDir = os.path.join(os.getcwd(), os.path.basename(fileName))
    if not os.path.exists(targetDir):
        os.makedirs(targetDir)

    if os.path.isfile(fileName) and fileName.endswith('.tar'):
        try:
            tar = tarfile.open(fileName, 'r:gz')
            tar.extractall(path=targetDir)
            tar.close()
            return targetDir
        except tarfile.TarError as e:
            print(f"Error extracting: {e}")
            return None
    else:
        print("File is not a valid tar archive")
        return None
