def hash_message(message: str, hash_function: str, salt: str = None) -> str:
    """
    Calculate the hash value of a message using a specified hash function.

    Args:
        message (str): The message to be hashed.
        hash_function (str): The hash function to use (e.g.,'md5','sha1','sha256','sha384','sha512').
        salt (str): An optional salt value to add randomness to the hash.

    Returns:
        str: A string representing the hash value in hexadecimal format.
    """
    if not isinstance(message, str):
        raise TypeError("Message must be a string")

    if not hash_function:
        raise TypeError("Hash function must be specified")

    if not any(hash_function in hashlib.algorithms_available or hash_function.startswith('sha') for hash_function in [hash_function]):
        raise ValueError("Unsupported hash function")

    if salt and not isinstance(salt, str):
        raise TypeError("Salt must be a string")

    if salt:
        if not salt.startswith('sha'):
            raise ValueError("Salt must start with'sha' if specified")

    algorithm = hashlib.new(hash_function.lower())

    if salt:
        # Ensure salt is 32 bytes long for SHA hash
        if hash_function.lower().startswith('sha'):
            salt_value = hashlib.sha256(salt.encode()).digest()
        else:
            salt_value = salt.encode()

        seed = secrets.choice([seed_val for seed_val in range(100000, 999999) if not salt and not any(str(seed_val) in message)])

        message_salted = f"{message}{str(seed)}{salt}"

    else:
        seed = secrets.choice([seed_val for seed_val in range(100000, 999999) if not any(str(seed_val) in message)])
        message_salted = f"{message}{str(seed)}"

    algorithm.update(message_salted.encode())

    return algorithm.hexdigest()
