def create_libvirt_volume_xml(params):
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")

    root = ET.Element('volume')
    root.set('type', 'block')

    dev_element = ET.SubElement(root, 'device')
    dev_element.set('path', params['device_path'])

    qos_element = ET.SubElement(root, 'qos')
    if 'qos_specs' in params:
        if not isinstance(params['qos_specs'], dict):
            raise ValueError("qos_specs must be a dictionary")

        total_bytes_element = ET.SubElement(qos_element, 'bandwidth')
        if 'total_bytes_sec' in params['qos_specs']:
            total_bytes_element.text = str(params['qos_specs']['total_bytes_sec'])
        else:
            raise ValueError("qos_specs must contain 'total_bytes_sec' key")

        read_iops_element = ET.SubElement(qos_element,'readIOPS')
        if'read_iops_sec' in params['qos_specs']:
            read_iops_element.text = str(params['qos_specs']['read_iops_sec'])
        else:
            raise ValueError("qos_specs must contain'read_iops_sec' key")

    auth_element = ET.SubElement(root, 'auth')
    if 'auth' in params:
        if not isinstance(params['auth'], dict):
            raise ValueError("auth must be a dictionary")
        if len(params['auth'])!= 3:
            raise ValueError("auth must contain exactly three keys")

        auth_method = params['auth'].keys()
        if auth_method!= ['type', 'username', 'password']:
            raise ValueError("Invalid auth method")

        auth_type = ET.SubElement(auth_element, 'type')
        auth_type.text = params['auth']['type']

        auth_username = ET.SubElement(auth_element, 'username')
        auth_username.text = params['auth']['username']

        auth_password = ET.SubElement(auth_element, 'password')
        auth_password.text = params['auth']['password']
    else:
        raise ValueError("auth must be provided")

    tree = ET.ElementTree(root)
    return ET.tostring(tree.getroot(), encoding='unicode')
