def alter_table_sql(table_name, old_column, new_column, new_field):
    column_definitions = []
    for key, value in new_field.items():
        if key == 'type': # For MySQL
            if value == 'boolean':
                column_definitions.append(f"`{new_column}` BOOL DEFAULT FALSE")
            elif value == 'integer':
                column_definitions.append(f"`{new_column}` INT DEFAULT 0")
            elif value =='string':
                required = 'NOT NULL' if value.get('nullable') == False else ''
                length = value.get('length')
                if length:
                    column_definitions.append(f"`{new_column}` VARCHAR({length}){required}")
                else:
                    column_definitions.append(f"`{new_column}` TEXT{required}")
            elif value == 'date':
                column_definitions.append(f"`{new_column}` DATE DEFAULT CAST('0000-00-00' AS DATE)")
            elif value == 'datetime':
                column_definitions.append(f"`{new_column}` DATETIME DEFAULT '0000-00-00 00:00:00'")
            elif value == 'timestamp':
                column_definitions.append(f"`{new_column}` TIMESTAMP DEFAULT CURRENT_TIMESTAMP")
        elif key == 'primary_key': 
            if value:
                column_definitions.append(f"ALTER TABLE `{table_name}` ALTER COLUMN `{new_column}` SET PRIMARY KEY")
        elif key == 'foreign_key': 
            if value:
                column_definitions.append(f"ALTER TABLE `{table_name}` ADD CONSTRAINT fk_{table_name}_{new_column} FOREIGN KEY (`{new_column}`) REFERENCES `{value[0]}` (`{value[1]}`)")

    if column_definitions:
        sql = f"ALTER TABLE `{table_name}` ALTER COLUMN `{old_column}` RENAME TO `{new_column}`; {'\n'.join(column_definitions)}"
    else:
        sql = f"ALTER TABLE `{table_name}` ALTER COLUMN `{old_column}` RENAME TO `{new_column}`"

