def download_file_in_parts(file_url, max_part_size, max_parts=100):
    file_name = file_url.split("/")[-1]
    file_size = int(os.path.getsize(file_name) if os.path.exists(file_name) else None)

    if file_size is None:
        try:
            response = requests.head(file_url)
            file_size = int(response.headers.get('content-length', 0))
        except requests.RequestException:
            print(f"Failed to retrieve file size: {file_url}")
            return {}

    if max_part_size <= 0:
        print("Part size must be greater than zero.")
        return {}

    if max_part_size >= file_size:
        print("Part size is too large.")
        return {}

    parts_limit_exceeded = max_parts!= 0 and file_size > max_part_size * max_parts
    num_parts = max_parts if parts_limit_exceeded else file_size // max_part_size

    part_size = file_size // num_parts
    last_part_size = file_size % num_parts

    part_offsets = [i * part_size + (1 if i < last_part_size else last_part_size) for i in range(num_parts)]

    print(f"File will be downloaded in {num_parts} parts of {part_size} bytes each ({part_size + last_part_size} bytes for the last part) from {file_url}")

    downloaded_parts = {}
    for i, part_offset in enumerate(part_offsets):
        url = f"{file_url}&byte_range={part_offset}-{part_offset + last_part_size if i == num_parts - 1 else (part_offset + part_size - 1)}"
        response = requests.get(url, stream=True)

        if response.status_code!= 206:
            print(f"Failed to download part {i+1}: {url}")
            return {}

        part_data = bytearray()
        for chunk in response.iter_content(chunk_size=1024):
            part_data.extend(chunk)
        downloaded_parts[f"part_{i+1}"] = part_data

