from flask import Flask, request, g, jsonify
import mysql.connector
app = Flask(__name__)

DATABASE = 'todo.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = mysql.connector.connect(
            user='root',
            password='password',
            host='127.0.0.1',
            database='todo'
        )
    return db

def query_db(query, args=(), one=False):
    cur = get_db().cursor()
    cur.execute(query, args)
    if one:
        ret = cur.fetchone()
        cur.close()
        get_db().commit()
        return ret
    else:
        ret = cur.fetchall()
        cur.close()
        get_db().commit()
        return ret

@app.route('/complete_task', methods=['POST'])
def complete_task():
    data = request.json
    task_id = data.get('task_id')
    if task_id:
        query = "UPDATE tasks SET completed = 1 WHERE id = %s"
        query_db(query, args=(task_id,))
    else:
        return jsonify({'error': 'task_id is required'}), 400
    return jsonify({'message': 'Task completed'}), 200

@app.route('/add_task', methods=['POST'])
def add_task():
    data = request.json
    task_name = data.get('task_name')
    if task_name:
        query = "INSERT INTO tasks (task_name, completed) VALUES (%s, 0)"
        query_db(query, args=(task_name,))
    else:
        return jsonify({'error': 'task_name is required'}), 400
    return jsonify({'message': 'Task added'}), 201

@app.route('/edit_task', methods=['POST'])
def edit_task():
    data = request.json
    task_id = data.get('task_id')
    new_task_name = data.get('task_name')
    if task_id and new_task_name:
        query = "UPDATE tasks SET task_name = %s WHERE id = %s"
        query_db(query, args=(new_task_name, task_id))
    else:
        return jsonify({'error': 'Both task_id and task_name are required'}), 400
    return jsonify({'message': 'Task updated'}), 200

@app.route('/delete_task', methods=['POST'])
def delete_task():
    data = request.json
    task_id = data.get('task_id')
    if task_id:
        query = "DELETE FROM tasks WHERE id = %s"
        query_db(query, args=(task_id,))
    else:
        return jsonify({'error': 'task_id is required'}), 400
    return jsonify({'message': 'Task deleted'}), 200

@app.route('/get_tasks', methods=['GET'])
def get_tasks():
    query = "SELECT * FROM tasks"
    ret = query_db(query)
    return jsonify([{'id': i[0], 'task_name': i[1], 'completed': i[2]} for i in ret])

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(debug=True)
