class LocationShareApp:
    def __init__(self):
        self.map = folium.Map(location=[37.7749, -122.4194], zoom_start=13)

    def create_map(self, locations):
        for _, row in locations.iterrows():
            folium.Marker(
                location=[row['lat'], row['lon']],
                popup=f"{row['name']}\n{row['description']}\n{row['address']}"
            ).add_to(self.map)
        return self.map._to_html()

    def process_data(self, data_path):
        try:
            locations = pd.read_csv(data_path)
            return locations
        except pd.errors.EmptyDataError:
            print("No data available.")
            return None
        except pd.errors.ParserError as e:
            print(f"Error parsing data: {e}")
            return None

def extract_lat_lon(address):
    import requests
    url = f"https://maps.googleapis.com/maps/api/geocode/json?address={address}&key=YOUR_API_KEY"
    response = requests.get(url)
    if response.status_code == 200:
        data = response.json()
        if data['status'] == 'OK':
            result = data['results'][0]
            location = result['geometry']['location']
            return location['lat'], location['lng']
    return None, None

def process_locations(self, data):
    address_to_lat_lon = {}
    for _, row in data.iterrows():
        address = row['address']
        if address not in address_to_lat_lon:
            lat, lon = extract_lat_lon(address)
            if lat is not None and lon is not None:
                address_to_lat_lon[address] = {'lat': lat, 'lon': lon}
        row['lat'], row['lon'] = address_to_lat_lon.get(address, (None, None))
    return data

def main():
    app = LocationShareApp()
    data_path = 'locations.csv'
    locations = app.process_data(os.path.join(os.getcwd(), data_path))
    if locations is not None:
        locations = app.process_locations(locations)
        if any(locations['lat'].isnull().values) or any(locations['lon'].isnull().values):
            print("Not all locations found, skipping rendering map.")
        else:
            html_map = app.create_map(locations)
            with open('map.html', 'w') as f:
                f.write(html_map)

if __name__ == '__main__':
    main()
