import urllib.parse

class CacheManager:
    def __init__(self, cache_folder='.cache', max_size=100):
        self.cache_folder = cache_folder
        self.max_size = max_size
        self.cache = {}

        if not os.path.exists(cache_folder):
            os.makedirs(cache_folder)

    def _hash_url(self, url):
        return hashlib.md5(url.encode()).hexdigest()

    def get(self, url):
        cache_path = os.path.join(self.cache_folder, f'{self._hash_url(url)}')
        try:
            with open(cache_path, 'rb') as file:
                return file.read()
        except OSError:
            return None

    def write(self, url, content):
        cache_path = os.path.join(self.cache_folder, f'{self._hash_url(url)}')
        with open(cache_path, 'wb') as file:
            file.write(content)
            self.cache[url] = content
            self._purge()

    def purge(self):
        for item in list(self.cache.keys()):
            cache_path = os.path.join(self.cache_folder, f'{self._hash_url(item)}')
            if not os.path.exists(cache_path):
                del self.cache[item]

    def _purge(self):
        if len(self.cache) >= self.max_size:
            self.purge()

class Browser:
    def __init__(self, cache_manager):
        self.cache_manager = cache_manager

    def visit(self, url):
        if url in self.cache_manager.cache:
            content = self.cache_manager.get(url)
        else:
            try:
                import requests
                content = requests.get(url).content
                self.cache_manager.write(url, content)
            except requests.RequestException as e:
                print(f"Error visiting {url}: {e}")
                return
        self.cache_manager.cache[url] = content
        self.cache_manager._purge()

    def get_cache(self):
        return self.cache_manager.cache.keys()

def example_usage():
    cache_manager = CacheManager(cache_folder='.cache')
    browser = Browser(cache_manager)
    browser.visit('https://www.example.com')
    browser.visit('https://www.google.com')
    print(browser.get_cache())
    return browser.get_cache()

if __name__ == "__main__":
    example_usage()
