import os
import re
import shutil
import stat
import threading

class LockedFileError(Exception):
    pass

class FileLocker:
    def __init__(self, path):
        self.path = path
        self.lock = threading.Lock()

    def __acquire__(self):
        try:
            self.lock.acquire()
            return True
        except Exception:
            raise LockedFileError

    def __release__(self):
        try:
            self.lock.release()
        except Exception:
            pass

class FilePermissionError(Exception):
    pass

def get_files(directory):
    files = []
    for root, dirs, dirnames in os.walk(directory):
        for name in dirnames:
            if name == '__pycache__':
                dirs.remove(name)
        for name in os.listdir(root):
            files.append(os.path.join(root, name))
    return files

def replace(files, pattern, replace):
    for file in files:
        locker = FileLocker(file)
        if not locker.__acquire__():
            raise LockedFileError
        try:
            with open(file, 'r') as f:
                text = f.read()
        except Exception:
            raise FilePermissionError

        new_text = re.sub(pattern, replace, text)

        with open(file, 'w') as f:
            f.write(new_text)

        os.chmod(file, stat.S_IREAD | stat.S_IWRITE | int(input('New permissions: ')))
    locker.__release__()

if __name__ == '__main__':
