import yaml
import json
import os

# Define a data structure to store the user's custom settings
class Settings:
    def __init__(self, filename):
        self.filename = filename
        self.data = self.load()

    def load(self):
        if os.path.exists(self.filename):
            try:
                with open(self.filename, 'r') as f:
                    return yaml.safe_load(f)
            except yaml.YAMLError as e:
                print(f"Error loading YAML config file: {e}")
                return {}
        else:
            return {}

    def save(self):
        try:
            with open(self.filename, 'w') as f:
                yaml.dump(self.data, f, default_flow_style=False)
        except yaml.YAMLError as e:
            print(f"Error saving YAML config file: {e}")

    def get(self, key, default=None):
        return self.data.get(key, default)

    def set(self, key, value):
        self.data[key] = value
        self.save()

class Config:
    def __init__(self):
        self.settings = Settings('config.yaml')

    def get_setting(self, key):
        return self.settings.get(key)

    def set_setting(self, key, value):
        self.settings.set(key, value)

# Usage example
config = Config()
config.set_setting('database_host', 'localhost')
config.set_setting('database_username', 'admin')
print(config.get_setting('database_host'))  # Output: localhost

# Example JSON config
class JsonSettings(Settings):
    def load(self):
        if os.path.exists(self.filename):
            try:
                with open(self.filename, 'r') as f:
                    return json.load(f)
            except json.JSONDecodeError as e:
                print(f"Error loading JSON config file: {e}")
                return {}
        else:
            return {}

    def save(self):
        try:
            with open(self.filename, 'w') as f:
                json.dump(self.data, f, indent=4)
        except json.JSONDecodeError as e:
            print(f"Error saving JSON config file: {e}")

# Usage example
json_config = JsonSettings('config.json')
json_config.set('database_host', 'localhost')
json_config.set('database_username', 'admin')
print(json_config.get('database_host'))  # Output: localhost
