import tarfile
import shutil
from pathlib import Path

class BackupTool:
    def __init__(self, backup_dir, backup_file):
        self.backup_dir = Path(backup_dir)
        self.backup_file = Path(backup_file)
        self.cache_dir = self.backup_dir / 'cache'
        self.cache_file = self.cache_dir / 'data.tar'

    def initialize_cache(self):
        if not self.cache_dir.exists():
            os.makedirs(self.cache_dir)

    def create_backup_archive(self, dir_to_backup, description):
        self.initialize_cache()
        with tarfile.open(self.cache_file, 'w') as tar:
            tar.add(dir_to_backup, arcname='')

    def differential_backup(self, new_dir_to_backup, old_tar_file):
        self.initialize_cache()
        try:
            with tarfile.open(old_tar_file, 'r') as original_tar, \
                 tarfile.open(self.cache_file, 'w') as new_tar:
                new_tar.add(new_dir_to_backup, arcname='')
                original_tar.extractall(self.cache_dir)
                for item in original_tar.getmembers():
                    if item.size == 0:
                        continue
                    stat = self.cache_dir / item.name
                    if not stat.exists():
                        item.size = 0
                    else:
                        item.size = stat.stat().st_size
                new_tar.add(self.cache_dir / 'data', arcname='')
        except FileNotFoundError:
            self.create_backup_archive(new_dir_to_backup, self.cache_file)

    def combine_backup(self):
        shutil.move(self.cache_file, self.backup_file)
