// index.js
import React, { useState, useEffect } from'react';
import fs from 'fs';
import path from 'path';
import { Image } from'react-native';

const StorageDirectory =FileSystem.DocumentDirectory;

const downloadAsset = (assetUrl, filename) => {
  const fileExists = async () => {
    return await fs.exists(path.join(StorageDirectory, filename));
  };

  const writeAsset = async (assetUrl) => {
    const fileStream = FileSystem.createFile(
      path.join(StorageDirectory, filename),
      '',
      'w'
    );
    const writer = new XMLHttpRequest();
    writer.open('GET', assetUrl, true);
    writer.responseType = 'arraybuffer';
    writer.onload = () => {
      const buffer = writer.response;
      const fileSize = buffer.byteLength;
      const filePointer = 0;
      const chunkSize = 1024;
      while (filePointer < fileSize) {
        const chunk = buffer.slice(filePointer, filePointer + chunkSize);
        fileStream.write(chunk);
        filePointer += chunkSize;
      }
    };
    writer.send();
    return path.join(StorageDirectory, filename);
  };

  const checkCache = async (filePointer) => {
    const fileSize = await fs.getInfoAsync(filePointer).then((result) => result.size);
    const cacheAge = (Date.now() - result.modificationTime) / 1000;
    return cacheAge < 60;
  };

  const getAsset = async (assetUrl, filename) => {
    const cachePath = await exportDefault.cache.get(assetUrl);
    if (cachePath) {
      const cacheAge = await checkCache(cachePath);
      if (cacheAge) return cachePath;
    }
    const assetPath = await writeAsset(assetUrl);
    exportDefault.cache.set(assetUrl, assetPath);
    return assetPath;
  };

  return getAsset;
};

// Usage:
const downloader = downloadAsset("https://example.com/image.jpg", "image.jpg");
const ImageComponent = () => {
  const [imageSource, setImageSource] = useState("");

  useEffect(() => {
    const download = async () => {
      const assetPath = await downloader();
      setImageSource(Asset.fromPath(assetPath));
    };
    download();
  }, []);

  return (
    <Image
      style={{ width: 300, height: 300 }}
      source={imageSource}
    />
  );
};

export default ImageComponent;
