import tarfile

class UserDataArchiver:
    def __init__(self, data_path, archive_path, archive_permissions):
        self.data_path = data_path
        self.archive_path = archive_path
        self.archive_permissions = archive_permissions

    def archive_data(self):
        if not os.path.exists(self.data_path):
            raise FileNotFoundError(f"Data path does not exist: {self.data_path}")

        if not os.path.exists(self.archive_path):
            os.makedirs(self.archive_path)

        archive_file_name = "archive_{}.tar.gz".format(len(os.listdir(self.data_path)))
        archive_file_path = os.path.join(self.archive_path, archive_file_name)

        try:
            with tarfile.open(archive_file_path, "w:gz") as tar:
                for file in os.listdir(self.data_path):
                    file_path = os.path.join(self.data_path, file)
                    if os.path.isfile(file_path):
                        if os.path.commonpath([file_path, self.archive_path]) == self.archive_path:
                            raise PermissionError("Cannot write archived file out of archive root")
                        tar.add(file_path, arcname=file)
                    elif os.path.isdir(file_path):
                        tar.add(file_path, arcname=file)

            permissions = stat.S_IRUSR | stat.S_IWUSR
            for perm in self.archive_permissions:
                if perm.lower() == 'g':
                    permissions |= stat.S_IRGRP | stat.S_IWGRP
                elif perm.lower() == 'o':
                    permissions |= stat.S_IROTH | stat.S_IWOTH

            os.chmod(archive_file_path, permissions)

            print(f"Archived data to {archive_file_path} with permissions: {stat.stat(archive_file_path).st_mode}")
        except Exception as e:
            raise Exception(f"Error archiving data: {str(e)}")

def main():
    data_path = input("Enter the path to data to archive: ")
    archive_path = input("Enter the path to archive (default is current directory): ") or '.'
    archive_permissions = input("Enter permissions on the archive (default is rwu): ").upper()
    archive_permissions = ''.join([perm for perm in archive_permissions if perm in 'RWO'])

    archiver = UserDataArchiver(data_path, archive_path, archive_permissions)
    archiver.archive_data()

if __name__ == "__main__":
