import compress_data
import pickle

class CompressedFS:
    def __init__(self, root_path, compression_threshold=1024 * 1024 * 10):
        self.root_path = root_path
        self.compression_threshold = compression_threshold
        self.compressed_files = {}
        self.uncompressed_dir = tempfile.mkdtemp()

    def compress_file(self, path):
        data = open(path, 'rb').read()
        compressed = compress_data.compress(data)
        return compressed

    def decompress_file(self, path):
        compressed = open(path, 'rb').read()
        return compress_data.decompress(compressed)

    def save_compressed(self, path, data):
        with open(f'{self.uncompressed_dir}/{path}', 'wb') as f:
            f.write(data)

    def load_compressed(self, path):
        with open(f'{self.uncompressed_dir}/{path}', 'rb') as f:
            return f.read()

    def touch(self, path):
        self.save_compressed(path, b'')

    def rm(self, path):
        try:
            os.remove(f'{self.uncompressed_dir}/{path}')
        except FileNotFoundError:
            pass

    def mkdir(self, path):
        os.makedirs(f'{self.uncompressed_dir}/{path}')

    def listdir(self, path):
        return os.listdir(self.uncompressed_dir)

    def read(self, path):
        return self.load_compressed(path)

    def create(self, path, data):
        self.save_compressed(path, self.compress_file(data))

    def stat(self, path):
        try:
            stat = os.stat(f'{self.uncompressed_dir}/{path}')
            return {'size': stat.st_size,'modified': stat.st_mtime}
        except FileNotFoundError:
            return None

    def write(self, path, data):
        with open(f'{self.uncompressed_dir}/{path}', 'wb') as f:
            self.save_compressed(path, f.write(data))

    def sync(self):
        files = self.listdir('')
        for file in files:
            path = f'{self.uncompressed_dir}/{file}'
            if os.path.getsize(path) > self.compression_threshold:
                compressed = self.compress_file(path)
                self.rm(path)
                self.save_compressed(file, compressed)

    def clean(self):
        shutil.rmtree(self.uncompressed_dir)
        self.uncompressed_dir = tempfile.mkdtemp()

def main():
    fs = CompressedFS('/tmp/compressedfs')

    while True:
        try:
            time.sleep(10)
            fs.sync()
        except KeyboardInterrupt:
            fs.clean()
            raise

