import zipfile
import datetime
import argparse
import logging
from contextlib import contextmanager

logging.basicConfig(level=logging.INFO)

@contextmanager
def archive_output(filename, mode='w:gz'):
    if mode == 'w:gz':
        with tarfile/open(filename, mode) as tar:
            yield tar
    elif mode == 'w:zip':
        with zipfile.ZipFile(filename, mode) as f:
            yield f
    else:
        raise ValueError("Invalid mode")

class StaleChecker:
    def __init__(self, db_path):
        self.db_path = db_path
        self.conn = sqlite3.connect(db_path)
        self.cursor = self.conn.cursor()

    def get_stale_records(self, days=30):
        self.cursor.execute('SELECT * FROM records WHERE created_at <?', (datetime.date.today() - datetime.timedelta(days=days),))
        return self.cursor.fetchall()

    def archive_stale_records(self, output_filename, compression='gz'):
        if compression not in ['gz', 'zip']:
            raise ValueError('Invalid compression type')

        with archive_output(output_filename, mode=f'w:{compression}') as output:
            for row in self.get_stale_records():
                output.writestr('record_' + str(row[0]) + '.json', str(row))

    def close(self):
        self.conn.close()

def main():
    parser = argparse.ArgumentParser(description='Identify and archive stale database records')
    parser.add_argument('--db-path', required=True, help='Path to SQLite database file')
    parser.add_argument('--output', required=True, help='Path to output archive file')
    parser.add_argument('--days', type=int, default=30, help='Number of days to consider as stale')
    parser.add_argument('--compression', default='gz', help='Compression type (gz, zip)')

    args = parser.parse_args()

    with StaleChecker(args.db_path) as checker:
        checker.archived_stale_records(args.output, args.compression)

if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        logging.error(f'Error: {e}')
