import os
import json
from kafka import KafkaProducer

class LogAggregator:
    def __init__(self, event_queue, kafka_bootstrap_servers, kafka_topic):
        self.event_queue = event_queue
        self.kafka_bootstrap_servers = kafka_bootstrap_servers
        self.kafka_topic = kafka_topic

        self.kafka_producer = KafkaProducer(
            bootstrap_servers=self.kafka_bootstrap_servers
        )

        self.logging_thread = Thread(target=self.run)
        self.logging_thread.daemon = True

    def run(self):
        while True:
            event = self.event_queue.get()
            self.handle_event(event)
            self.event_queue.task_done()

    def handle_event(self, event):
        try:
            self.kafka_producer.send(
                self.kafka_topic,
                value=json.dumps(event).encode('utf-8')
            ).add_callback(self.on_send_success)
        except Exception as e:
            logging.error(f"Error sending event to Kafka: {e}")

    def on_send_success(self, metadata):
        logging.info(f"Event sent to Kafka: id={metadata.offset}, value={metadata.value()}")

    def start(self):
        self.logging_thread.start()

class EventGenerator:
    def __init__(self, event_queue):
        self.event_queue = event_queue

    def generate_events(self):
        while True:
            event = {
                "timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "payload": f"Event {datetime.datetime.now().microsecond}"
            }
            self.event_queue.put(event)

def main():
    # Create a queue for event handling
    event_queue = queue.Queue()

    # Create an event generator
    event_generator = EventGenerator(event_queue)
    Thread(target=event_generator.generate_events).start()

    # Create a log aggregator
    log_aggregator = LogAggregator(
        event_queue=event_queue,
        kafka_bootstrap_servers=["localhost:9092"],
        kafka_topic="my_topic"
    )
    log_aggregator.start()

    # Use a keep-alive thread to avoid exit
    while True:
        pass

if __name__ == "__main__":
    import datetime
    main()
