class LinkRewriter:
    def __init__(self, blocked_sites):
        self.blocked_sites = set(blocked_sites)

    def is_blocked(self, url):
        try:
            parsed_url = urllib.parse.urlparse(url)
            return parsed_url.netloc in self.blocked_sites
        except ValueError:
            return False

    def rewrite_link(self, url):
        if self.is_blocked(url):
            return None  # Do not rewrite blocked links
        parts = urllib.parse.urlparse(url)
        query_params = urllib.parse.parse_qs(parts.query)
        query_params['rewritten'] = 'true'
        rewritten_url = urllib.parse.urlunparse((parts.scheme, parts.netloc, parts.path, parts.params, urllib.parse.urlencode(query_params), parts.fragment))
        return rewritten_url

class SecurityRiskTokenizer:
    def split_args(self, string):
        try:
            return string.split('+', 1)
        except IndexError:
            # Unbalanced + in string
            pass

class LinkRewriterFactory:
    def __init__(self, blocked_sites):
        self.blocked_sites = blocked_sites

    def create_rewriter(self):
        return LinkRewriter(self.blocked_sites)

    def run(self, url):
        rewriter = self.create_rewriter()
        return rewriter.rewrite_link(url)

