        y = 0
        for cls in classes:
            diagram.add(Shape.rectangle(x, y, 20, 30, fill_color=(0.8, 0.4, 0.2)))
            x += 30

            diagram.add(Text(len(cls).__str__(), x + 25, y + 20, font_size=10, text_color=(1, 1, 1)))
            x += 15

            diagram.add(Line(x, y, x + 100, y, stroke_color=(1, 1, 1)))
            x += 100
            y += 40

        return diagram

