    def draw_rect(self, obj, x, y):
        diagram.add(Shape.rectangle(x, y, 10, 10, fill_color=(1, 0, 0)))

class Line(ast.NodeVisitor):
    def __init__(self):
        self.code_lines = []

    def visit_FunctionDef(self, node):
        self.code_lines.append(node.name)

        for child in node.body:
            if isinstance(child, ast.ClassDef):
                for item in ast.iter_child_nodes(child):
                    if isinstance(item, ast.AnnAssign):
                        if item.target.id =='self':
                            for child2 in ast.iter_child_nodes(item.value):
                                if isinstance(child2, ast.Call):
                                    self.code_lines.append(child.name + '.' + item.target.id + '.' + item.annotation.id)
                                break
            self.visit(child)

    def get_code_lines(self):
        return self.code_lines

