import os
import shutil
import tarfile
import zipfile
import rarfile
from loguru import logger


class ArchiveUtility:
    def __init__(self):
        self.archive_types = ['.tar', '.zip', '.rar']

    def backup(self, source_path, archive_path):
        """Create an archive of the given source directory.

        Args:
        source_path (str): Path to the source directory or file
        archive_path (str): Path to save the archive

        Returns:
        bool: True if successful, False otherwise
        """
        if not any(archive_path.endswith(ext) for ext in self.archive_types):
            logger.error("Invalid archive type")
            return False

        if os.path.isfile(source_path):
            # If source is a file, pack it into an archive
            return self.pack_single_file(source_path, archive_path)
        else:
            # If source is a directory, create an archive of it
            return self.pack_directory(source_path, archive_path)

    def pack_single_file(self, file_path, archive_path):
        with tarfile.open(archive_path, 'w') as tar:
            tar.add(file_path)
            logger.info(f'File {file_path} archived successfully')
            return True

    def pack_directory(self, directory_path, archive_path):
        if not os.path.exists(directory_path):
            logger.error(f'Directory {directory_path} not found')
            return False

        with tarfile.open(archive_path, 'w:gz') as tar:
            tar.add(directory_path, arcname=os.path.split(directory_path)[1])
            logger.info(f'Directory {directory_path} archived successfully')
            return True

    def restore(self, archive_path, target_path):
        """Restore the given archive file to the target path.

        Args:
        archive_path (str): Path to the archive file
        target_path (str): Path to restore the archive

        Returns:
        bool: True if successful, False otherwise
        """
        if not any(archive_path.endswith(ext) for ext in self.archive_types):
            logger.error("Invalid archive type")
            return False

        with self.get_archive(archive_path) as archive:
            try:
                archive.extractall(target_path)
                logger.info('Archive restored successfully')
                return True
            except Exception as e:
                logger.error(f'Archive extraction failed: {e}')
                return False

    def get_archive(self, archive_path):
        if archive_path.endswith('.tar'):
            return tarfile.open(archive_path, 'r')
        elif archive_path.endswith('.zip'):
            return zipfile.ZipFile(archive_path, 'r')
        elif archive_path.endswith('.rar'):
            return rarfile.RarFile(archive_path, 'r')


if __name__ == "__main__":
    tool = ArchiveUtility()
    tool.backup('./path/to/directory', './path/to/archive.tar')
    tool.backup('./file.txt', './file.txt.tar')
    tool.restore('./path/to/archive.tar', './restored/path')
