    parser = argparse.ArgumentParser(description='Bulk rename files based on user-specified patterns')
    parser.add_argument('-r', '--root', help='Root directory for bulk rename', required=True)
    parser.add_argument('-f', '--find', help='File pattern to find', required=True)
    parser.add_argument('-r', '--replace', help='File pattern to replace', required=True)
    parser.add_argument('-o', '--outputdir', help='Output directory path', required=False)
    parser.add_argument('-p', '--permissions', help='Permissions to set (in octal format, e.g., 0o755)', required=False)
    return parser.parse_args()

def rename_files(root_dir, find, replace):
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            if find in file:
                old_file = os.path.join(root, file)
                new_file = file.replace(find, replace)
                new_file_path = os.path.join(root, new_file)
                os.rename(old_file, new_file_path)

def set_permissions(file, permissions):
    try:
        os.chmod(file, int(permissions, 8))
    except PermissionError:
        print(f'Permission denied to set permissions for {file}')

def main():
    args = parse_args()
    rename_files(args.root, args.find, args.replace)
    if args.outputdir:
        for root, dirs, files in os.walk(args.root):
            for file in files:
                if args.find in file:
                    old_file = os.path.join(root, file)
                    new_file = file.replace(args.find, args.replace)
                    new_file_path = os.path.join(args.outputdir, new_file)
                    os.rename(old_file, new_file_path)
    if args.permissions:
