import os
from typing import Dict, Any

class FileTypeConverter:
    @staticmethod
    def convert_file(in_type: str, out_type: str, in_file: str, out_file: str) -> bool:
        if in_type == 'csv' and out_type == 'json':
            return FileTypeConverter.csv_to_json(in_file, out_file)
        elif in_type == 'json' and out_type == 'csv':
            return FileTypeConverter.json_to_csv(in_file, out_file)
        else:
            print("Incompatible input or output types")
            return False

    @staticmethod
    def csv_to_json(csv_file: str, json_file: str) -> bool:
        import csv
        import json
        try:
            with open(csv_file, 'r') as csv_file_open:
                csv_reader = csv.DictReader(csv_file_open)
                data = [row for row in csv_reader]
            with open(json_file, 'w') as json_file_open:
                json.dump(data, json_file_open, indent=4)
            return True
        except Exception as e:
            print(f"Error occurred while converting {csv_file} to {json_file}: {str(e)}")
            return False

    @staticmethod
    def json_to_csv(json_file: str, csv_file: str) -> bool:
        import json
        try:
            with open(json_file, 'r') as json_file_open:
                data = json.load(json_file_open)
            with open(csv_file, 'w', newline='') as csv_file_open:
                fieldnames = data[0].keys() if data else []
                csv_writer = csv.DictWriter(csv_file_open, fieldnames=fieldnames)
                csv_writer.writeheader()
                csv_writer.writerows(data)
            return True
        except Exception as e:
            print(f"Error occurred while converting {json_file} to {csv_file}: {str(e)}")
            return False

def main():
    in_type = input("Enter the input file type (csv|json): ")
    out_type = input("Enter the output file type (csv|json): ")
    in_file = input("Enter the input file path: ")
    out_file = input("Enter the output file path: ")

    if FileTypeConverter.convert_file(in_type, out_type, in_file, out_file):
        print(f"Conversion successful from {in_type} to {out_type} in {out_file}")
    else:
        print("Conversion failed")

if __name__ == "__main__":
    main()
