import eyed3
from urllib.request import urlretrieve
from urllib.error import HTTPError

def get_media_files(directory):
    return [os.path.join(root, file)
            for root, dirs, files in os.walk(directory)
            for file in files if file.endswith(('.mp3', '.wav', '.ogg'))]

def load_track(file):
    audio = eyed3.load(file)
    return {
        'title': audio.tag.title,
        'artist': audio.tag.artist,
        'album': audio.tag.album,
        'genre': audio.tag.genre,
        'duration': audio.info.time_secs,
        'url': 'file://' + file
    }

def parse_directory(directory):
    tracks = {}
    files = get_media_files(directory)
    for file in files:
        try:
            tracks[file] = load_track(file)
        except Exception as e:
            print(f"Error parsing file {file}: {e}")
    return tracks

def download_media_file(url):
    try:
        filename = url.split('/')[-1]
        urlretrieve(url, filename)
        return filename
    except HTTPError as e:
        print(f"Error downloading {url}: {e}")
        return None

def parse_and_download(directory, url):
    tracks = parse_directory(directory)
    for file, track in tracks.items():
        if track['url'].startswith('file://') and not os.path.exists(track['url'][7:]):
            download_url = urllib.parse.urlparse(track['url'])[1]
            print(f"Downloading file from {download_url}")
            downloaded_file = download_media_file(download_url)
            if downloaded_file:
                track['url'] = 'file://' + downloaded_file
        yield track

def main():
    parser = argparse.ArgumentParser(description='Music player app')
    parser.add_argument('--directory', help='Directory to parse', required=True)
    args = parser.parse_args()
    try:
        for track in parse_and_download(args.directory, None):
            print(json.dumps(track))
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

