    mother_id = db.Column(db.Integer, db.ForeignKey('person.id'))
    children = db.relationship('Person', remote_side=[id], backref='children', lazy='dynamic')
    photos = db.relationship('Photo', backref='person', lazy='dynamic')
    memories = db.relationship('Memory', backref='person', lazy='dynamic')

class Photo(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    person_id = db.Column(db.Integer, db.ForeignKey('person.id'))
    image_url = db.Column(db.String(200), nullable=False)

class Memory(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    person_id = db.Column(db.Integer, db.ForeignKey('person.id'))
