        birthdate = datetime.datetime.strptime(request.form['birthdate'], '%Y-%m-%d').date()
        gender = request.form['gender']
        if request.form['father_id']:
            father = Person.query.get(request.form['father_id'])
        else:
            father = None
        if request.form['mother_id']:
            mother = Person.query.get(request.form['mother_id'])
        else:
            mother = None
        person = Person(name=name, birthdate=birthdate, gender=gender, father=father, mother=mother)
        db.session.add(person)
        db.session.commit()
        return redirect(url_for('show_family_tree'))
    return render_template('create_person.html')

@app.route('/add_photo', methods=['POST'])
def add_photo():
    person_id = request.form['person_id']
    image_url = request.form['image_url']
    photo = Photo(person_id=person_id, image_url=image_url)
    db.session.add(photo)
    db.session.commit()
    return redirect(url_for('show_family_tree'))

@app.route('/add_memory', methods=['POST'])
def add_memory():
    person_id = request.form['person_id']
    description = request.form['description']
    date_posted = datetime.datetime.strptime(request.form['date_posted'], '%Y-%m-%d').date()
    memory = Memory(person_id=person_id, description=description, date_posted=date_posted)
    db.session.add(memory)
    db.session.commit()
    return redirect(url_for('show_family_tree'))

@app.route('/')
def index():
