        for root, dirs, files in os.walk(self.path):
            for item in dirs + files:
                item_path = os.path.join(root, item)
                self.fs_perms[item_path] = {
                    'permissions': oct(os.stat(item_path).st_mode)[-3:],
                    'owner': os.stat(item_path).st_uid,
                    'group': os.stat(item_path).st_gid,
                   'size': os.stat(item_path).st_size,
                   'modified': os.stat(item_path).st_mtime
                }

    def display_perms(self):
        self._collect_perms()
        for path, perms in self.fs_perms.items():
            print(f"{path}:")
            print(f"  Permissions: {perms['permissions']}")
            print(f"  Owner: {perms['owner']}")
            print(f"  Group: {perms['group']}")
            print(f"  Size: {perms['size']}")
            print(f"  Modified: {perms['modified']}")
            print()

    def display_tree(self, level=0):
        self._collect_perms()
        print("Augmented File Browser")
        for path, perms in self.fs_perms.items():
            path_display = "  " * level + path
            perms_display = f"PERMS: {perms['permissions']}. OWNER: {perms['owner']}. GROUP: {perms['group']}. " \
                           f"SIZE: {perms['size']}. MODIFIED: {perms['modified']}. "
            print(f"{path_display}: {perms_display}")

class AugmentedFileBrowser:
    def __init__(self, path):
        self.browser = FileBrowser(path)

    def run(self):
        self.browser.display_tree()
        action = input("Enter file path to display details, 't' to display tree, 'q' to quit: ")
        while action.lower()!= 'q':
            if action == 't':
                self.browser.display_tree()
            elif action.startswith("f_"):
                self.browser.display_perms()
                print(f"Currently displaying file {action[2:]}")
            else:
                logger.info(f"Unknown action {action}")
                print("Invalid action")
            action = input("Enter file path to display details, 't' to display tree, 'q' to quit: ")

if __name__ == "__main__":
    browser = AugmentedFileBrowser('.')
    browser.run()
