import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from collections import deque

class WebIndexer:
    def __init__(self, start_urls, max_depth, timeout=5):
        self.start_urls = start_urls
        self.max_depth = max_depth
        self.timeout = timeout
        self.index = {}

    def crawl(self):
        queue = deque(self.start_urls)
        visited = set()

        while queue:
            url = queue.popleft()
            if url in visited:
                continue
            visited.add(url)

            try:
                response = requests.get(url, timeout=self.timeout)
                response.raise_for_status()
            except requests.RequestException as e:
                print(f"Error crawling {url}: {e}")
                continue

            soup = BeautifulSoup(response.text, 'html.parser')

            title = soup.find('title')
            if title:
                self.index[url] = title.text.strip()

            for link in soup.find_all('a'):
                href = link.get('href')
                if not href:
                    continue

                absolute_url = urljoin(url, href)
                if absolute_url not in self.index and absolute_url not in visited:
                    queue.append(absolute_url)

            self.max_depth -= 1
            if self.max_depth == 0:
                break

    def __str__(self):
        indexed_pages = ", ".join(url for url, title in self.index.items())
        return f"Indexed {len(self.index)} pages: {indexed_pages}"

def main():
    start_urls = ["http://example.com"]
    indexer = WebIndexer(start_urls, max_depth=2)
    indexer.crawl()
    print(indexer)

if __name__ == "__main__":
    main()
