            server_process = psutil.Process(server)
            cpu_percent = server_process.cpu_percent()
            memory_percent = server_process.memory_percent()
            if cpu_percent > self.config['thresholds']['cpu'] or memory_percent > self.config['thresholds']['memory']:
                self.save_anomaly(server, cpu_percent, memory_percent)
                self.logger.info(f'Anomaly detected on {server} with cpu: {cpu_percent}% and memory: {memory_percent}%')
