    """Returns total size of a specific path in MB."""
    try:
        bytes_size = pathlib.Path(path).lstat().st_size
        return round(bytes_size / (1024 * 1024), 2)
    except Exception as e:
        return str(e)

def get_largest_files_by_ext(path, top_n=5):
    """Returns a list of the top n largest files grouped by extension."""
    counts = defaultdict(list)
    for root, dirs, files in os.walk(path):
        for f in files:
            ext = os.path.splitext(f)[1]
            file_path = os.path.join(root, f)
            file_size = get_disk_usage_path(file_path)
            if file_size is not None:
                counts[ext].append((file_path, file_size))

    result = {}
    for ext, files in counts.items():
        sorted_files = sorted(files, key=lambda x: x[1], reverse=True)
        result[ext] = sorted_files[:top_n]

    return result

