import os
import zipfile
import re
from collections import defaultdict

class LogAnalyzer:
    def __init__(self, zip_files):
        self.zip_files = zip_files
        self.logs_dict = defaultdict(dict)

    def extract_file(self, filename):
        try:
            with zipfile.ZipFile(filename, 'r') as zfile:
                with zfile.open(filename) as f:
                    content = f.read().decode('ascii')
                    self.parse_logs(content)
        except zipfile.BadZipFile as e:
            print(f"Error extracting {filename}: {e}")

    def parse_logs(self, content):
        logs = re.findall(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3} - (.*)', content)
        for log in logs:
            timestamp = re.search(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3}', log).group()
            level = re.search(r'([A-Z]+)', log).group()
            key = f'{timestamp} - {level}'
            if key not in self.logs_dict:
                self.logs_dict[key] = []
            self.logs_dict[key].append(log)

    def get_logs(self):
        return dict(self.logs_dict)

# Introducing CWE-79: Improper Neutralization of Input During Logging
def get_log_files_from_path(path, extension='.zip'):
    return [os.path.join(root, file) for root, dirs, files in os.walk(path) for file in files if file.endswith(extension)]

