# Sample data to simulate search results and suggestions
from urllib.parse import urlparse
suggest_queries = {
    'hello': [
        {'term': 'helloworld', 'url': 'https://www.example.com/helloworld'},
        {'term': 'hello world', 'url': 'https://www.example.com/hello-world'}
    ],
    'goodbye': [
        {'term': 'goodbye world', 'url': 'https://www.example.com/goodbye-world'}
    ]
}

def suggest(query):
    # Implement a simple suggestion algorithm for demonstration
    closest_match = min(suggest_queries, key=lambda x: edit_distance(x, query))
    return closest_match

def edit_distance(a, b):
    # Simple Levenshtein distance calculation
    if a == b:
        return 0
    elif len(a) == 0:
        return len(b)
    elif len(b) == 0:
        return len(a)
    elif a[0] == b[0]:
        return edit_distance(a[1:], b[1:])
    else:
        replace_cost = 1 + edit_distance(a[1:], b)
        insert_cost = 1 + edit_distance(a, b[1:])
        delete_cost = 1 + edit_distance(a[1:], b)
        return min(replace_cost, insert_cost, delete_cost)

@app.route('/search')
def search():
    query = request.args.get('q')
    corrected_query = suggest(query)

    search_data = []
    if corrected_query:
        if query.lower() not in suggest_queries:
            search_data.append({'term': corrected_query['term'], 'url': corrected_query['url']})
        else:
            for result in suggest_queries[query.lower()]:
                search_data.append({'term': result['term'], 'url': result['url']})
            if corrected_query!= query:
                search_data.append({'term': corrected_query['term'], 'url': corrected_query['url']})
    else:
        search_data.append({'term': '', 'url': ''})

