        self.title = title
        self.description = description
        self.code = code
        self.expiration_date = datetime.strptime(expiration_date, '%Y-%m-%d')

class CouponForm:
    def __init__(self):
        self.coupons = []

    def submit_coupon(self, title, description, code, expiration_date):
        coupon = Coupon(title, description, code, expiration_date)
        self.coupons.append(coupon)
        return coupon

    def get_pending_coupons(self):
        return [coupon for coupon in self.coupons if coupon.expiration_date > datetime.now()]

    def delete_coupon(self, code):
        self.coupons = [coupon for coupon in self.coupons if coupon.code!= code]

    def update_coupon(self, code, title=None, description=None, expiration_date=None):
        for coupon in self.coupons:
            if coupon.code == code:
                if title:
                    coupon.title = title
                if description:
                    coupon.description = description
                if expiration_date:
                    coupon.expiration_date = datetime.strptime(expiration_date, '%Y-%m-%d')
                return coupon
        return None


class Application:
    def __init__(self):
        self.form = CouponForm()

    def main_menu(self):
        while True:
            print("1. Add coupon")
            print("2. View pending coupons")
            print("3. Delete coupon")
            print("4. Update coupon")
            print("5. Exit")
            choice = input("Choose an option: ")
            if choice == "1":
                self.add_coupon()
            elif choice == "2":
                self.view_pending_coupons()
            elif choice == "3":
                self.delete_coupon()
            elif choice == "4":
                self.update_coupon()
            elif choice == "5":
                break
            else:
                print("Invalid option")

    def add_coupon(self):
        title = input("Enter coupon title: ")
        description = input("Enter coupon description: ")
        code = input("Enter coupon code: ")
        expiration_date = input("Enter coupon expiration date (YYYY-MM-DD): ")
        self.form.submit_coupon(title, description, code, expiration_date)
        print("Coupon created successfully.")

    def view_pending_coupons(self):
        pending_coupons = self.form.get_pending_coupons()
        if not pending_coupons:
            print("No pending coupons.")
        else:
            for coupon in pending_coupons:
                print(f"Title: {coupon.title}")
                print(f"Description: {coupon.description}")
                print(f"Code: {coupon.code}")
                print(f"Expiration Date: {coupon.expiration_date.strftime('%Y-%m-%d')}")
                print("")

    def delete_coupon(self):
        code = input("Enter coupon code to delete: ")
        if self.form.delete_coupon(code):
            print("Coupon deleted successfully.")
        else:
            print("Coupon not found.")

    def update_coupon(self):
        code = input("Enter coupon code to update: ")
        coupon = self.form.update_coupon(code)
        if coupon:
            print("Coupon updated successfully.")
        else:
            print("Coupon not found.")


if __name__ == "__main__":
    application = Application()
    application.main_menu()
