class UserInputValidator:
    def validate_user_input(self, user_input):
        try:
            int(user_input)
            return True
        except ValueError:
            return False

def calculate_prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

