import os
import shutil
import tempfile
import datetime
import filecmp

def find_temp_files(directory):
    temp_files = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            try:
                stats = os.stat(path)
                ctime = datetime.datetime.fromtimestamp(stats.st_ctime)
                mtime = datetime.datetime.fromtimestamp(stats.st_mtime)
                if ctime < mtime and mtime < datetime.datetime.now() - datetime.timedelta(days=30):
                    temp_files.append(path)
            except OSError as e:
                pass
    return temp_files

def remove_temp_files(files, directory):
    for file in files:
        try:
            shutil.rmtree(file)
        except OSError as e:
            if e.errno == 21:  # directory not empty
                dest = os.path.join(directory, os.path.basename(file))
                if os.path.exists(dest):
                    if filecmp.cmpfiles(file, dest, files=True):
                        shutil.rmtree(file)
                else:
                    print(f"Could not find matching directory {dest}")
            else:
                print(f"Error removing file: {file}")

def main():
    directory = '.'  # current working directory
    temp_files = find_temp_files(directory)
    remove_temp_files(temp_files, directory)
    print("Removed {} temp files".format(len(temp_files)))

if __name__ == "__main__":
    main()
