def rotate_log(log_file, max_age=7):
    permissions = stat.S_IRUSR | stat.S_IWUSR | stat.S_IROTH | stat.S_IWOTH | stat.S_IRGRP | stat.S_IWGRP # 0o644 permissions
    max_size = 10 * 1024 * 1024 # 10MB
