            open(new_log_path, 'w').write("")
            shutil.copy(log_file, new_log_path, follow_symlinks=True)
            os.chmod(new_log_path, permissions)
            os.remove(log_file)
        else:
            for file in os.listdir():
                if file.startswith("log_file rotated at"):
                    file_path = os.path.join(os.getcwd(), file)
                    mtime = datetime.fromtimestamp(os.path.getmtime(file_path))
                    if (datetime.now() - mtime).days >= max_age:
