    def make_artifact(self):
        # Create artifact directory
        artifact_dir = self.source_dir / f'{self.artifact_name}_v{self.dependencies[self.Dependency.PROJECT_VERSION]}'
        artifact_dir.mkdir(parents=True, exist_ok=True)

        # Copy build files to artifact directory
        for file_name in self.source_dir.glob("*"):
            if file_name.name!= '__init__.py' and file_name.is_file():
                shutil.copy(file_name, artifact_dir)

        # Create a tarball of the artifact
        with tarfile.open(f'{artifact_dir}/{self.artifact_name}_v{self.dependencies[self.Dependency.PROJECT_VERSION]}.tar.gz', 'w:gz') as tar:
            tar.add(artifact_dir)

        # Clean up
        shutil.rmtree(artifact_dir)

class BuildSystem(ABC):
    def __init__(self, config):
        self.config = config

    @abstractmethod
    def build(self):
        pass

class BuildSystemImpl(BuildSystem):
    def build(self):
        self.config.make_artifact()

