from enum import Enum
from typing import Dict

class QuestionType(Enum):
    """
    Enum for question types
    """
    RATING = 1
    TEXT = 2

class Question:
    """
    Class representing a question
    """
    def __init__(self, prompt: str, question_type: QuestionType):
        self.prompt = prompt
        self.question_type = question_type

class RatingQuestion(Question):
    """
    Class representing a rating question
    """
    def __init__(self, prompt: str, min_rating: int = 1, max_rating: int = 5):
        super().__init__(prompt, QuestionType.RATING)
        self.min_rating = min_rating
        self.max_rating = max_rating

class TextQuestion(Question):
    """
    Class representing a text question
    """
    def __init__(self, prompt: str):
        super().__init__(prompt, QuestionType.TEXT)

class Survey:
    """
    Class representing a survey
    """
    def __init__(self):
        self.questions = []
        self.results: Dict[Question, list[float]] = {}

    def add_question(self, question: Question):
        self.questions.append(question)
        self.results[question] = []

    def get_result(self, question: Question):
        return self.results.get(question, [])

    def add_response(self, question: Question, rating: float):
        if isinstance(question, RatingQuestion):
            if question.question_type == QuestionType.RATING and question.min_rating <= rating <= question.max_rating:
                if question not in self.results:
                    self.results[question] = []
                self.results[question].append(rating)
            else:
                raise ValueError(f"Invalid rating value: {rating}")
        elif question.question_type == QuestionType.TEXT:
            if question not in self.results:
                self.results[question] = []
            self.results[question].append(rating)
        else:
            raise ValueError(f"Unsupported question type: {question.question_type}")

# Example usage
surveys = Survey()

rating_question = RatingQuestion("How would you rate our service?", 1, 5)
text_question = TextQuestion("Any additional feedback?")

surveys.add_question(rating_question)
surveys.add_question(text_question)

surveys.add_response(rating_question, 4)
surveys.add_response(text_question, "Great experience!")

print(surveys.results)
