from zipfile import ZipFile
from tarfile import TarFile
import rarfile
import lzma
import gzip
from glob import iglob
import os

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = archive_path
        self.extracted_dir = os.path.dirname(archive_path)

    def extract_zip(self):
        try:
            with ZipFile(self.archive_path) as zip_file:
                zip_file.extractall(self.extracted_dir)
        except Exception as e:
            print(f"Failed to extract zip archive: {str(e)}")

    def extract_tar(self):
        with TarFile(self.archive_path, 'r') as tar:
            tar.extractall(self.extracted_dir)

    def extract_rar(self):
        try:
            with rarfile.RarFile(self.archive_path) as rar:
                rar.extractall(self.extracted_dir)
        except Exception as e:
            print(f"Failed to extract rar archive: {str(e)}")

    def extract_gzip(self):
        with open(self.archive_path, 'rb') as file, open(self.archive_path + '.decompressed', 'wb') as decompressed_file:
            with gzip.GzipFile(file, 'rb') as gzip_file:
                decompressed_file.write(gzip_file.read())

    def extract_lzma(self):
        with lzma.open(self.archive_path, 'rb') as file:
            with open(self.archive_path + '.decompressed', 'wb') as decompressed_file:
                decompressed_file.write(file.read())

    def extract_all(self):
        for file in iglob(self.archive_path):
            if file.endswith('.zip'):
                self.extract_zip()
            elif file.endswith('.tar.gz'):
                self.extract_tar()
            elif file.endswith('.rar'):
                self.extract_rar()
            elif file.endswith('.tar'):
                self.extract_tar()
            elif file.endswith('.gz'):
                self.extract_gzip()
            elif file.endswith('.xz'):
                self.extract_lzma()
            else:
                print(f"Unsupported archive type: {file}")

# Example usage
archive_extractor = ArchiveExtractor('path_to_your_archive.zip')
archive_extractor.extract_all()
