import os
import shutil
import tarfile
import datetime
import getpass
import stat
import tempfile
import pathlib

def get_archivedir(path):
    return os.path.join(path, 'archive')

def get_archivename(username, date):
    return f'{username}-{date}.tgz'

def get_archive_params():
    username = input('Enter username: ')
    path = input('Enter path to archive data from: ')
    destination = get_archivedir(path)
    try:
        os.mkdir(destination)
    except FileExistsError:
        pass
    permissions = input('Enter permissions (rwx, x, w, r): ')
    return username, path, destination, permissions

def is_valid_permissions(user_perm):
    valid_perms = {'r', 'x', 'w'}
    return set(user_perm).issubset(valid_perms)

def set_permissions(stat_info, permissions):
    perm_map = {'r': stat.S_IRUSR, 'x': stat.S_IXUSR, 'w': stat.S_IWUSR}
    for perm in set(permissions):
        if perm in perm_map:
            stat_info.st_mode |= perm_map[perm]
        elif perm == 'r':
            stat_info.st_mode |= stat.S_IRUSR, stat.S_IRGRP, stat.S_IROTH
        elif perm == 'w':
            stat_info.st_mode |= stat.S_IWUSR, stat.S_IWGRP, stat.S_IWOTH
        elif perm == 'x':
            stat_info.st_mode |= stat.S_IXUSR, stat.S_IXGRP, stat.S_IXOTH
    return stat_info

def archiveloader(user, path, destination, permissions):
    try:
        files = os.listdir(path)
        tar_file = get_archivename(user, datetime.datetime.now().strftime('%Y%m%d'))
        file_path = os.path.join(destination, tar_file)
        with tarfile.open(file_path, "w:gz") as tar:
            for f in files:
                tar.add(os.path.join(path, f))
        stat_info = pathlib.Path(file_path).stat()
        stat_info = set_permissions(stat_info, permissions)
        pathlib.Path(file_path).chmod(stat_info.st_mode)
    except Exception as e:
        print(f'Error archiving files: {e}')

def main():
    user, path, destination, permissions = get_archive_params()
    if not is_valid_permissions(permissions):
        print('Invalid permissions')
        return
    archiveloader(user, path, destination, permissions)
    print(f'Archive created: {get_archivename(user, datetime.datetime.now().strftime("%Y%m%d"))}')

if __name__ == "__main__":
    if os.geteuid()!= 0:
        print('Please run this script as root.')
    else:
        main()
