def generate_file_hashes(directory):
    """
    Generates a dictionary of file hashes for all files in the given directory and its subdirectories.

    Args:
        directory (str): Path to the directory to scan.

    Returns:
        dict: A dictionary where keys are file paths and values are their corresponding SHA-256 hashes.
