                hashes[fp] = hashlib.sha256(open(fp, 'rb').read()).hexdigest()
    except FileNotFoundError as e:
        print(f"Error: Directory not found - {e}")
    except PermissionError as e:
        print(f"Error: Permission denied to access a file - {e}")
