class APIDocExtractor:
    def __init__(self, app):
        self.app = app

    def extract_docstrings(self):
        routes = []
        for instance in (
            self.app
            or getattr(self.app.wsgi_app, "application", None, type(self.app.__class__))
        ).__mro__:
            for name in dir(instance):
                obj = getattr(instance, name)
                if inspect.isclass(obj):
                    if name.endswith("View") or issubclass(obj, Flask):
                        for item in obj.__dict__.values():
                            if inspect.isclass(item) and (
                                hasattr(item, "__doc__") or hasattr(item, "route")
                            ):
                                for attr in dir(item):
                                    attrObj = getattr(item, attr)
                                    if inspect.isfunction(attrObj) and hasattr(attrObj, "__doc__"):
                                        route_name = attrObj.__name__
                                        route_path = f"/{attrObj.__name__.lower()}"
                                        tags = []
                                        summary = attrObj.__doc__
                                        operation_id = attrObj.__name__
                                        responses = {
                                            "200": OpenAPIResponse("text/plain", summary)
                                        }
                                        methods = ["GET"]
                                        if hasattr(attrObj, "method"):
                                            methods = [attrObj.method.__name__]
                                        routes.append(
                                            OpenAPIResponse(
                                                route_name=route_name,
                                                route_path=route_path,
                                                tags=tags,
                                                summary=summary,
                                                operation_id=operation_id,
                                                responses=responses,
                                                methods=methods,
                                            )
                                        )

        return routes

def generate_openapi(app, out_file):
    api = APIDocExtractor(app)
    routes = api.extract_docstrings()
    spec = OpenAPISpec(
        openapi="3.0.0",
        info={
            "title": "flask-api",
            "description": "API documentation generated from Flask application",
            "version": "1.0.0",
        },
        routes=routes,
    )
    OpenAPIConverter()(spec, **spec.flattened_spec)
    specs = spec.flattened_spec
    with open(out_file, "w") as f:
        f.write(specs)

if __name__ == "__main__":
    from myapp import app

    generate_openapi(app, "openapi.yaml")
