from pathlib import Path

class LogDataExtractor:
    def __init__(self, zip_file_path):
        self.zip_file_path = Path(zip_file_path)

    def extract_zipped_log(self):
        try:
            with zipfile.ZipFile(self.zip_file_path, 'r') as zip_ref:
                temp_dir = tempfile.mkdtemp()
                zip_ref.extractall(temp_dir)
                return temp_dir
        except Exception as e:
            print(f"Error while extracting zip file: {e}")
            return None

    def read_log_data(self, data_dir):
        try:
            log_files = []
            for file in Path(data_dir).rglob('*.log'):
                with open(file, 'r') as log_file:
                    content = log_file.read()
                    log_files.append(content)
            return '\n'.join(log_files)
        except Exception as e:
            print(f"Error while reading log files: {e}")
            return None

    def extract_data(self):
        data_dir = self.extract_zipped_log()
        if data_dir:
            return self.read_log_data(data_dir)
        else:
            return None

def process_log_data(log_data):
    pattern = r"error=(.*)"
    matches = re.findall(pattern, log_data, re.DOTALL)
    return matches

def main():
    log_extractor = LogDataExtractor('path/to/log/zipfile.zip')
    log_data = log_extractor.extract_data()
    if log_data:
        errors = process_log_data(log_data)
        if errors:
            print(f"Errors: {errors}")
        else:
            print("No errors found.")
    else:
        print("Failed to extract and read log data.")

if __name__ == "__main__":
    main()
