from flask import Flask, request, render_template_string, request_form_data
from jinja2 import Template

app = Flask(__name__)

class Component:
    def __init__(self, name, type):
        self.name = name
        self.type = type

    def to_html(self):
        component_html = f"""
        <div class="component">
            <h3>{{ self.name }}</h3>
            <p>Type: {{ self.type }}</p>
        </div>
        """
        return Template(component_html).render(self=self)


class Oscillator(Component):
    def __init__(self, name):
        super().__init__(name, "Oscillator")


class Filter(Component):
    def __init__(self, name):
        super().__init__(name, "Filter")


class Sequencer(Component):
    def __init__(self, name):
        super().__init__(name, "Sequencer")


@app.route('/synth', methods=['GET', 'POST'])
def synth():
    name = request.args.get('name', 'Untitled Synth')
    description = request.args.get('description', '')
    components = [
        Oscillator('Oscillator 1'),
        Filter('Filter 1'),
        Sequencer('Sequencer 1'),
    ]

    if request.method == 'POST':
        for part in request.form:
            if 'name' in part:
                component = eval(part.split('-')[0])
                component.name = request.form[part]
                components.append(component)
            if 'type' in part:
                part = part.split('=')
                component = components[int(part[0])]
                component.type = request.form[part[1]]

    synth_html = """
    <h1>{{ name }}</h1>
    <p>{{ description }}</p>
    <h2>Components</h2>
    {% for component in components %}
      {{ component.to_html() }}
    {% endfor %}
    <form method="post">
    {% for i, component in enumerate(components) %}
      {{ component.to_html() }}
      Name: <input type="text" name="{{ i }}-name" value="{{ component.name }}">
      Type: <input type="text" name="{{ i }}-type" value="{{ component.type }}">
      <br>
    {% endfor %}
      <input type="submit" value="Save">
    </form>
    """
    return render_template_string(synth_html, name=name, description=description, components=components)


if __name__ == '__main__':
    app.run(debug=True)
```

