            if user.name == username:
                return user.interests
        return None

class BioFormatter:
    @staticmethod
    def format_bio(bio):
        lines = bio.split('\n')
        formatted_bio = ''
        for line in lines:
            formatted_bio += '-'+ line + '\n'
        return formatted_bio

