class ErrorReporter:
    def __init__(self, log_file):
        self.log_file = log_file
        self.logger = logging.getLogger('error_logger')
        self.logger.setLevel(logging.ERROR)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler = logging.FileHandler(self.log_file)
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def send_log(self, error_type, message):
        self.logger.error(f'{error_type} - {message}')

    def send_exception(self, exception):
        import traceback
        message = f'Exception Caught: {str(exception)}\n{traceback.format_exc()}'
        self.send_log('Exception', message)

    def send_info(self, message):
        self.logger.info(message)


class IngestionSystem:
    def __init__(self, error_reporter):
        self.error_reporter = error_reporter

    def ingest_logs(self, error_type, message):
        if error_type and message:
            self.error_reporter.send_log(error_type, message)

    def ingest_exceptions(self, exception):
        self.error_reporter.send_exception(exception)

    def ingest_info(self, message):
        self.error_reporter.send_info(message)


# Example usage
