def extract(tar_file):
    try:
        tar = tarfile.open(tar_file, 'r:gz')
        tar.extractall()
    except FileNotFoundError:
        print(f"File '{tar_file}' not found.")
    except tarfile.TarError as e:
        print(f"Error extracting tarball: {e}")
    finally:
        if 'tar' in locals():
            tar.close()

# Example usage:
extract('example.tar.gz')
