import requests
import os
import csv
import xml.etree.ElementTree as ET

class CurationTool:
    def __init__(self, output_dir):
        self.output_dir = output_dir
        os.makedirs(self.output_dir, exist_ok=True)

    def _download_dataset(self, url):
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()
            with open(os.path.basename(url), 'wb') as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)
        except Exception as e:
            raise Exception(f"Failed to download dataset from {url}: {str(e)}")

    def _extract_dataset(self, file_path):
        if file_path.endswith('.csv'):
            with open(file_path, 'r') as f:
                reader = csv.reader(f)
                headers = next(reader)
                print(f"{file_path} has {len(headers)} columns")
        elif file_path.endswith('.xml'):
            tree = ET.parse(file_path)
            root = tree.getroot()
            print(f"{file_path} has {len(root)} entities")

    def collect_dataset(self, url):
        try:
            filename = os.path.basename(url)
            full_path = os.path.join(self.output_dir, filename)
            self._download_dataset(url)
            self._extract_dataset(full_path)
        except Exception as e:
            print(f"Failed to collect dataset from {url}: {str(e)}")

    def run(self, urls):
        for url in urls:
            self.collect_dataset(url)


if __name__ == "__main__":
    urls = ["https://example.com/dataset1.csv", "https://example.com/dataset2.xml"]
    curation_tool = CurationTool('./datasets')
    curation_tool.run(urls)
