import os
import hashlib
import tarfile
from datetime import datetime

class SourceControlSystem:
    def __init__(self):
        self.checkouts = {}

    def add_file(self, file_path):
        file_hash = self._calculate_hash(file_path)
        self.checkouts[file_hash] = {"file_path": file_path, "last_updated": datetime.now()}

    def remove_file(self, file_hash):
        if file_hash in self.checkouts:
            del self.checkouts[file_hash]

    def update_file(self, file_path):
        file_hash = self._calculate_hash(file_path)
        if file_hash in self.checkouts:
            self.checkouts[file_hash]["last_updated"] = datetime.now()
        else:
            self.add_file(file_path)

    def checkout(self, file_path):
        file_hash = self._calculate_hash(file_path)
        if file_hash in self.checkouts:
            with open(file_path, 'r+') as f:
                while True:
                    data = f.read(4096)
                    if not data:
                        break
                    print(data, end='')

    def _calculate_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

def create_tarball(file_hashes, output_path):
    with tarfile.open(output_path, 'w:gz') as tar:
        for file_hash, checkout_info in file_hashes.items():
            file_path = checkout_info["file_path"]
            tarinfo = tarfile.TarInfo(name=os.path.basename(file_path))
            tarinfo.size = os.path.getsize(file_path)
            tarinfo.mtime = datetime.timestamp(checkout_info["last_updated"])
            tar.addfile(tarinfo, open(file_path, 'rb'))

def extract_tarball(input_path, destination_path):
    with tarfile.open(input_path, 'r:gz') as tar:
        tar.extractall(destination_path)

def main():
    s = SourceControlSystem()
    s.add_file('example.txt')
    s.add_file('example2.txt')
    s.update_file('example.txt')

    create_tarball(s.checkouts, 'backup.tar.gz')

    extract_tarball('backup.tar.gz', '/path/to/destination')
    s.checkout('/path/to/destination/example.txt')

if __name__ == "__main__":
    main()
