import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin
from urllib.parse import urlparse
from queue import Queue
from threading import Thread
from typing import List

class LinkCrawler:
    def __init__(self, start_url):
        self.start_url = start_url
        self.broken_links = set()
        self.visited = set()

    def is_valid_url(self, url: str) -> bool:
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except ValueError:
            return False

    def extract_links(self, soup):
        links = []
        for a in soup.find_all('a', href=True):
            href = a['href']
            if self.is_valid_url(href):
                links.append(urljoin(self.start_url, href))
        return links

    def crawl(self, url):
        try:
            response = requests.head(url)
            if response.status_code >= 400:
                Thread(target=self.crawl, args=(url,)).start()
            else:
                self.visited.add(url)
                soup = BeautifulSoup(response.content, 'html.parser')
                for link in self.extract_links(soup):
                    if link not in self.visited:
                        Thread(target=self.crawl, args=(link,)).start()
        except Exception as e:
            self.broken_links.add(url)
            print(f"Error: {url} - {e}")

    def run(self):
        queue = Queue()
        queue.put(self.start_url)
        while not queue.empty():
            url = queue.get()
            self.crawl(url)
        print(f"Broken links: {len(self.broken_links)}")

def main():
    crawler = LinkCrawler('http://example.com')
    crawler.run()

if __name__ == "__main__":
    main()
