    process = subprocess.Popen(['bash', '-c', f'cd {path} && make'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()
    if process.returncode!= 0:
        raise ValueError(f'Build failed: {error.decode}')

def run_tests(tests_path):
    process = subprocess.Popen(['bash', '-c', f'cd {tests_path} && pytest'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()
    if process.returncode!= 0:
        raise ValueError(f'Tests failed: {error.decode()}')

