from urllib.parse import urljoin, urlparse
from collections import deque

class Crawler:
    def __init__(self, start_url):
        self.start_url = start_url
        self.visited = set()
        self.queue = deque([start_url])

    def crawl(self):
        while self.queue:
            url = self.queue.popleft()
            if url not in self.visited:
                self.visited.add(url)
                self._crawl_page(url)

    def _crawl_page(self, url):
        try:
            response = requests.get(url)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching {url}: {e}")
            return

        soup = BeautifulSoup(response.text, 'html.parser')

        for link in soup.find_all('a', href=True):
            link_url = urljoin(url, link['href'])
            if urlparse(link_url).netloc == urlparse(self.start_url).netloc:
                if link_url not in self.visited:
                    self.queue.append(link_url)

        for img in soup.find_all('img', src=True):
            img_url = urljoin(url, img['src'])
            try:
                response = requests.head(img_url)
                response.raise_for_status()
            except requests.exceptions.RequestException:
                print(f"Broken image: {img_url}")

        for img in soup.find_all('img', srcset=True):
            img_url = urljoin(url, img['srcset'].split(',')[0].split(' ')[0])
            try:
                response = requests.head(img_url)
                response.raise_for_status()
            except requests.exceptions.RequestException:
                print(f"Broken image: {img_url}")

import argparse

