from collections import defaultdict
import threading

class WebLogAnalyzer:
    def __init__(self, url, max_threads=10):
        self.url = url
        self.max_threads = max_threads
        self.threads = []
        self.urls_to_check = []

    def extract_links(self, url):
        response = requests.get(url)
        soup = BeautifulSoup(response.text, 'html.parser')
        return [link.get('href') for link in soup.find_all('a') if link.get('href')]

    def scan_urls(self, url):
        try:
            response = requests.head(url)
            if response.status_code == 404:
                return f"404: {url}"
            else:
                return f"{url} is live"
        except Exception as e:
            return f"Error: {e}"

    def run(self):
        start_url = self.url
        self.urls_to_check = self.extract_links(start_url)

        for _ in range(self.max_threads):
            thread = threading.Thread(target=self.scan_url_loop)
            thread.start()
            self.threads.append(thread)

        for thread in self.threads:
            thread.join()

        result = defaultdict(list)
        for status in self.results:
            result[status].append(status)
        return dict(result)

    def scan_url_loop(self):
        while self.urls_to_check:
            url = self.urls_to_check.pop(0)
            self.results.append(self.scan_urls(url))

if __name__ == "__main__":
    web_log_analyzer = WebLogAnalyzer('https://example.com')
    web_log_analyzer.run()
    print(web_log_analyzer.results)

    dead_links = [link for link, status in web_log_analyzer.results.items() if '404:' in status]
    print("Dead links:")
    print(dead_links)
