            soup = BeautifulSoup(html, "html.parser")
            for script in soup(["script", "style"]):
                script.decompose()
            filename = f"{url.split('/')[-1]}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.html"
            with open(filename, "w") as f:
                f.write(soup.prettify())
