import urllib.parse

class URLInspector:
    def __init__(self, url):
        self.url = url

    def get_response(self):
        try:
            response = requests.head(self.url)
            return response
        except requests.ConnectionError:
            return None

    def get_metadata(self, response):
        if response is None:
            return None

        metadata = {
           'response_code': response.status_code,
           'redirect_url': response.history[-1].url if len(response.history) > 1 else None,
            'headers': dict(response.headers)
        }
        return metadata

    def get_html(self, response):
        if response is None:
            return None

        try:
            html_result = response.text
            return html.unescape(html_result)
        except ValueError:
            return None

def parse_url(url):
    try:
        parsed_url = urllib.parse.urlparse(url)
        return {'scheme': parsed_url.scheme, 'netloc': parsed_url.netloc}
    except ValueError:
        return None

def main():
    parser = argparse.ArgumentParser(description='URL inspection tool')
    parser.add_argument('url', type=str)
    args = parser.parse_args()

    url = args.url
    if not parse_url(url):
        print("Invalid URL")
        return

    inspector = URLInspector(url)
    response = inspector.get_response()
    metadata = inspector.get_metadata(response)
    html_result = inspector.get_html(response)

    print('Metadata:')
    for key, value in metadata.items():
        print(f'{key}: {value}')

    print('HTML:')
    if html_result is not None:
        print(html_result)

if __name__ == '__main__':
    main()
