import stat
import datetime

def backup_db(db_path, backup_dir, backup_permissions):
    """Backup database files by copying them to a backup directory, allowing the user to specify permissions."""
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)

    db_name = os.path.basename(db_path)
    backup_name = f"{db_name}_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
    backup_path = os.path.join(backup_dir, backup_name)

    try:
        shutil.copy2(db_path, backup_path)

        if backup_permissions is not None:
            try:
                os.chmod(backup_path, backup_permissions)
            except PermissionError:
                print(f"Error setting permissions for {backup_path}. Permissions may not be set correctly.")
        else:
            print(f"Backup successful for {db_path}. No permissions set.")

        print(f"Backup created at: {backup_path}")

    except Exception as e:
        print(f"Error backing up {db_path}: {str(e)}")

if __name__ == "__main__":
    db_path = input("Enter database file path: ")
    backup_dir = input("Enter backup directory path (default for 'backups'): ") or 'backups'
    backup_permissions = input("Enter backup file permissions (default for None): ")

    if backup_permissions:
        try:
            backup_permissions = int(backup_permissions, 8)
        except ValueError:
            print("Invalid permissions number.")
            exit(1)

    backup_db(db_path, backup_dir, backup_permissions)
