        self.max_pages = 1000  # maximum number of pages to crawl
        self.downloaded_pages = 0
        self.html_dir = 'pages'

    def create_directory(self):
        if not os.path.exists(self.html_dir):
            os.makedirs(self.html_dir)

    def get_html(self, url):
        try:
            response = requests.get(url)
            response.raise_for_status()
            return response.text
        except requests.RequestException as e:
            print(f"Failed to retrieve {url}: {e}")
            return None

    def parse_html(self, html):
        soup = BeautifulSoup(html, 'html.parser')
        return soup

    def extract_urls(self, soup):
        return [a['href'] for a in soup.find_all('a', href=True) if a['href'].startswith(self.base_url)]

    def save_page(self, page_id, soup, html):
        with open(os.path.join(self.html_dir, f'page_{page_id}.html'), 'w') as f:
            f.write(html)

    def crawl(self, url, page_id):
        html = self.get_html(url)
        if html is not None:
            soup = self.parse_html(html)
            self.save_page(page_id, soup, html)
            print(f"Downloaded page {page_id}: {url}")
            self.downloaded_pages += 1
            additional_urls = self.extract_urls(soup)
            for i, u in enumerate(additional_urls):
                self.crawl(u, page_id + i + 1)
                if self.downloaded_pages >= self.max_pages:
                    break

    def run(self):
        self.create_directory()
        self.crawl(self.base_url, 1)
        print(f"Downloaded {self.downloaded_pages} pages.")

