def get_file_metadata(path):
    try:
        return {
            'file_name': os.path.basename(path),
            'file_path': path,
            'file_size': os.path.getsize(path),
            'created_time': datetime.fromtimestamp(os.path.getctime(path), tz=pytz.utc),
           'modified_time': datetime.fromtimestamp(os.path.getmtime(path), tz=pytz.utc),
            'accessed_time': datetime.fromtimestamp(os.path.getatime(path), tz=pytz.utc),
            'permissions': oct(os.stat(path).st_mode & 0xFFF)[2:].zfill(3)
        }
    except Exception as e:
        return None

def get_file_type(path):
    return os.path.isfile(path) and 'file' or 'directory'

def process_file(path):
    try:
        metadata = get_file_metadata(path)
        if metadata is not None:
            file_type = get_file_type(path)
            permissions = oct(os.stat(path).st_mode & 0xFFF)[2:].zfill(3)
            print(f'File: {metadata["file_name"]}\nType: {file_type}\nSize: {metadata["file_size"]}\nCreated: {metadata["created_time"]}\nModified: {metadata["modified_time"]}\nAccessed: {metadata["accessed_time"]}\nPermissions:{permissions}\n')

        try:
            # vulnerable to integer overflow in case of very large file sizes
