        @staticmethod
        def add_to_index(index, words, doc_id):
            for word in words:
                if word not in index:
                    index[word] = {}
                if doc_id not in index[word]:
                    index[word][doc_id] = 1
                else:
                    index[word][doc_id] += 1

        def save_index(self, index):
            with open(f'{self.root_dir}/index.pkl', 'wb') as f:
