import tarfile
import requests
import os

def download_package(package_name):
    url = f"https://files.pythonhosted.org/packages/source/{package_name[0]}/{package_name}/{package_name}-{package_name.split('-')[-1]}.tar.gz"
    r = requests.get(url)
    with open(f'{package_name}.tar.gz', 'wb') as f:
        f.write(r.content)

def extract_package(package_name):
    try:
        tar = tarfile.open(f'{package_name}.tar.gz')
        tar.extractall()
        os.chdir(package_name.split('-')[0])
        tar.extractall()
        os.chdir('../')
        for directory in os.listdir():
            if os.listdir(directory):
                os.chdir(directory)
                os.system("python setup.py build")
                os.system("python setup.py install")
                os.chdir('../')
            else:
                os.rmdir(directory)
        os.remove(f"{package_name}.tar.gz")
        os.chdir('../')
    except NameError:
        os.remove(f'{package_name}.tar.gz')
        raise
    except Exception as e:
        print(f"Failed to install package: {e}")
        os.remove(f'{package_name}.tar.gz')
        raise

def uninstall_package(package_name):
    try:
        os.system(f"pip uninstall {package_name}")
    except Exception as e:
        print(f"Failed to uninstall package: {e}")

def install_package(package_name):
    try:
        download_package(package_name)
        extract_package(package_name)
    except Exception as e:
        print(f"Failed to install package: {e}")

def uninstall_install_package(package_name):
    uninstall_package(package_name)
    install_package(package_name)

install_package('numpy-1.22.3')
