from zipfile import ZipFile
import bz2
from urllib import request
import io

class WebScraper:
    def __init__(self, url):
        self.url = url

    def download_file(self, url):
        response = requests.get(url)
        return response.content

    def decompress_bz2(self, data):
        try:
            return bz2.decompress(data)
        except Exception as e:
            print(f"Error decompressing bz2 file: {e}")

    def decompress_zip(self, data):
        try:
            with ZipFile(io.BytesIO(data)) as zf:
                return zf.read(zf.namelist()[0])
        except Exception as e:
            print(f"Error decompressing zip file: {e}")

    def fetch_and_decompress(self):
        page = requests.get(self.url)
        soup = BeautifulSoup(page.text, 'html.parser')
        data_links = []
        for link in soup.find_all('a'):
            if link.get('href'):
                if link.get('href').endswith(('.bz2', '.zip')):
                    data_links.append(link.get('href'))
        data_url = 'your download link'
        data = self.download_file(data_url)
        if data_url.endswith('.bz2'):
            decompressed_data = self.decompress_bz2(data)
        elif data_url.endswith('.zip'):
            decompressed_data = self.decompress_zip(data)
        return decompressed_data

class DataFrameCreator:
    def __init__(self, data, url):
        self.data = data
        self.url = url

    def load_csv(self):
        try:
            return pd.read_csv(io.BytesIO(self.data))
        except Exception as e:
            print(f"Error loading csv: {e}")

def fetch_and_create_dataframe(url):
    scraper = WebScraper(url)
    decompressed_data = scraper.fetch_and_decompress()
