import tarfile
import zipfile
import rarfile
import shutil
from PIL import Image
import io
from io import BytesIO
import os

class ArchiveUtil:
    @staticmethod
    def extract_tarball(tarball_path, output_dir):
        """Extracts a tarball archive to a given directory."""
        with tarfile.open(tarball_path, 'r:gz') as tar:
            tar.extractall(output_dir)

    @staticmethod
    def extract_zipfile(zipfile_path, output_dir):
        """Extracts a zip archive to a given directory."""
        with zipfile.ZipFile(zipfile_path, 'r') as zip_ref:
            zip_ref.extractall(output_dir)

    @staticmethod
    def extract_rarfile(rarfile_path, output_dir):
        """Extracts a rar archive to a given directory."""
        with rarfile.RarFile(rarfile_path, mode='r') as rar_ref:
            rar_ref.extractall(output_dir)

    @staticmethod
    def extract_jarfile(jarfile_path, output_dir):
        """Extracts a jar archive to a given directory."""
        shutil.unpack_archive(jarfile_path, output_dir)

    @staticmethod
    def extract_images_from_folder(folder_path, output_dir):
        """Extracts all images from a given folder and saves them in a new directory."""
        images = []
        for filename in os.listdir(folder_path):
            if filename.lower().endswith(('.png', '.jpg', '.jpeg', '.gif', '.bmp', '.tiff', '.tif')):
                img_path = os.path.join(folder_path, filename)
                image = Image.open(img_path)
                bytes_streams = BytesIO()
                image.save(bytes_streams, 'JPEG')
                images.append((filename, bytes_streams.getvalue()))
        if images:
            output_dir_path = os.path.join(output_dir, 'images')
            os.makedirs(output_dir_path, exist_ok=True)
            with open(os.path.join(output_dir_path, 'images.tar'), 'wb') as f:
                for img in images:
                    f.write(img[1])

    @staticmethod
    def extract_images_from_archive(archive_path, output_dir):
        """Extracts all images from a given archive and saves them in a new directory."""
        if archive_path.endswith('.tar.gz'):
            ArchiveUtil.extract_tarball(archive_path, output_dir)
            images = ArchiveUtil.extract_images_from_folder(output_dir, output_dir)
        elif archive_path.endswith('.zip'):
            ArchiveUtil.extract_zipfile(archive_path, output_dir)
            images = ArchiveUtil.extract_images_from_folder(output_dir, output_dir)
        elif archive_path.endswith('.rar'):
            ArchiveUtil.extract_rarfile(archive_path, output_dir)
            images = ArchiveUtil.extract_images_from_folder(output_dir, output_dir)
        elif archive_path.endswith('.jar'):
            ArchiveUtil.extract_jarfile(archive_path, output_dir)
            images = ArchiveUtil.extract_images_from_folder(output_dir, output_dir)
        return images

# Example usage
ArchiveUtil.extract_tarball('input.tar.gz', 'output_dir')
ArchiveUtil.extract_zipfile('input.zip', 'output_dir')
ArchiveUtil.extract_rarfile('input.rar', 'output_dir')
ArchiveUtil.extract_jarfile('input.jar', 'output_dir')
