    def __init__(self, url, depth):
        self.url = url
        self.depth = depth
        self.queue = Queue()
        self.visited = set()
        self.images = []

    def get_response(self, url):
        try:
            return requests.get(url)
        except requests.RequestException as e:
            print(f"Error fetching {url}: {e}")
