        for link in links:
            href = link.get('href')
            if href and href.startswith('http'):
                yield urljoin(base_url, href)

    def is_good_link(self, link):
        return any(ext in link for ext in ['.html', '.jpg', '.png', '.gif', '.bmp', '.pdf'])

    def crawl(self):
