        if start_response:
            tree = html.fromstring(start_response.text)
            soup = BeautifulSoup(str(tree), 'lxml')
            for link in self.extract_links(soup, self.url):
                if self.is_good_link(link) and self.depth > 0:
                    self.queue.put(link)
            self.visited.add(self.url)
        while not self.queue.empty():
            new_url = self.queue.get()
            if new_url not in self.visited:
                new_start_response = self.get_response(new_url)
                if new_start_response:
                    self.visited.add(new_url)
                    tree = html.fromstring(new_start_response.text)
                    soup = BeautifulSoup(str(tree), 'lxml')
                    for link in self.extract_links(soup, new_url):
                        if self.is_good_link(link) and self.depth > 1:
                            self.queue.put(link)

    def download_images(self):
        self.crawl()
        while not self.queue.empty():
            new_url = self.queue.get()
            if new_url not in self.visited:
                response = self.get_response(new_url)
                if response:
                    tree = html.fromstring(response.text)
                    soup = BeautifulSoup(str(tree), 'lxml')
                    for src in soup.find_all('img'):
                        image_url = src.get('src')
                        if image_url and self.is_good_link(image_url):
                            urlretrieve(image_url, image_url.split("/")[-1])

def extract_images(image_archive):
    tar = tarfile.open(image_archive)
    for filename in tar.getnames():
        if filename.endswith(('.jpg', '.png', '.gif', '.bmp', '.pdf')):
            tar.extractmembers(filename)
            tar.extract(filename, './images/')
    tar.close()

